from itertools import cycle
DIRS={'u':(-1,0),'r':(0,1),'d':(1,0),'l':(0,-1)}
def solve(inp):
    h=len(inp); w=len(inp[0])
    seed=[(r,c) for r in range(h) for c in range(w) if inp[r][c]==3][0]
    r0,c0=seed
    dist={'u':r0,'d':h-1-r0,'l':c0,'r':w-1-c0}
    first=min(dist,key=dist.get)  # ties -> dict order u,d,l,r? need up preferred
    for d in 'udlr':
        if dist[d]<dist[first]: first=d
    # rotation clockwise: u->r->d->l ; start index
    order='urdl'
    seq=order[order.index(first):]+order[:order.index(first)]
    g=[row[:] for row in inp]
    r,c=r0,c0
    for i,dch in enumerate(cycle(seq)):
        seg=2*(i//2+1)
        if seg>2*(h+w): break
        dr,dc=DIRS[dch]
        truncated=False
        for _ in range(seg):
            nr,nc=r+dr,c+dc
            if not(0<=nr<h and 0<=nc<w) or g[nr][nc]==2:
                truncated=True; break
            if g[nr][nc]==3:
                return g  # own path: end silently, keep drawn
            g[nr][nc]=3; r,c=nr,nc
        # continue regardless (truncation by boundary/2)
    return g
for name,(i_,o_) in [('D1',(G['Demo pair 1 input'],G['Demo pair 1 output'])),('D2',(G['Demo pair 2 input'],G['Demo pair 2 output']))]:
